diff --git a/src/auth/refresh.ts b/src/auth/refresh.ts
--- /dev/null
+++ b/src/auth/refresh.ts
@@ -0,0 +1,12 @@
+import { createSession, getSession, revokeSession, type Session } from "./session.ts";
+
+/** Lifetime of the replacement session; keep in step with the TTL login() starts sessions with. */
+const REFRESHED_SESSION_TTL_MS = 12 * 60 * 60 * 1000;
+
+/** Revoke the token's session and start a fresh one for the same user, or undefined if there is none. */
+export function refreshSession(token: string): Session | undefined {
+  const current = getSession(token);
+  if (!current) return undefined;
+  revokeSession(token);
+  return createSession(current.userId, { ttlMs: REFRESHED_SESSION_TTL_MS });
+}

